import 'dart:math' as math;

import 'package:flutter/material.dart';

/// MiliConfig's neon shield emblem: a glowing green shield outline around a rounded M whose
/// two uprights end in dots, on a deep black-green field. Matches the launcher icon
/// (images/icon/, generated by scripts/make_brand_assets.py).
class MiliShieldLogo extends StatelessWidget {
  final double size;
  final Color? primaryColor;
  final Color? accentColor;

  const MiliShieldLogo({
    super.key,
    this.size = 28,
    this.primaryColor,
    this.accentColor,
  });

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final primary = primaryColor ?? scheme.primary;
    final accent = accentColor ?? scheme.secondary;
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(
        painter: _NeonShieldPainter(primary: primary, accent: accent),
      ),
    );
  }
}

class _NeonShieldPainter extends CustomPainter {
  final Color primary;
  final Color accent;

  const _NeonShieldPainter({required this.primary, required this.accent});

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.shortestSide / 128.0;
    final rect = Offset.zero & size;

    // Deep field with the faint green halo behind the mark.
    final halo = Rect.fromCircle(
      center: rect.center,
      radius: size.shortestSide * 0.52,
    );
    canvas.drawCircle(
      rect.center,
      size.shortestSide * 0.52,
      Paint()
        ..shader = RadialGradient(
          colors: [
            primary.withValues(alpha: 0.16),
            const Color(0xFF04140A).withValues(alpha: 0.5),
            Colors.transparent,
          ],
          stops: const [0, 0.62, 1],
        ).createShader(halo),
    );

    final shield = _shieldPath(10 * s, 126 * s, 10 * s, 126 * s);
    final m = _mPath(10 * s, 126 * s, 10 * s, 126 * s);

    final glowColor = primary;
    // Bloom: wide blurred strokes under the crisp neon line.
    for (final blur in [16.0, 8.0, 3.0]) {
      final paint = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = (5.6 + blur * 0.22) * s
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = glowColor.withValues(alpha: blur > 8 ? 0.30 : 0.22)
        ..maskFilter = MaskFilter.blur(BlurStyle.normal, blur * s);
      canvas.drawPath(shield, paint);
      paint
        ..strokeWidth = (7.4 + blur * 0.18) * s
        ..strokeCap = StrokeCap.round
        ..color = accent.withValues(alpha: blur > 8 ? 0.24 : 0.18);
      canvas.drawPath(m, paint);
    }

    final shieldFill = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [
          const Color(0xFF08240F).withValues(alpha: 0.78),
          const Color(0xFF03100A).withValues(alpha: 0.92),
        ],
      ).createShader(rect);
    canvas.drawPath(shield, shieldFill);

    final shieldLine = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 6.6 * s
      ..strokeJoin = StrokeJoin.round
      ..color = Color.lerp(primary, Colors.white, 0.18)!;
    canvas.drawPath(shield, shieldLine);

    final mLine = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 9.4 * s
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..shader = LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: [accent, primary],
      ).createShader(rect);
    canvas.drawPath(m, mLine);

    // The three dots: the M's shoulders and the centre of the V.
    final dot = Paint()..color = Color.lerp(accent, primary, 0.35)!;
    final dotGlow = Paint()
      ..color = primary.withValues(alpha: 0.55)
      ..maskFilter = MaskFilter.blur(BlurStyle.normal, 3.2 * s);
    for (final p in _mDots(10 * s, 126 * s, 10 * s, 126 * s)) {
      canvas.drawCircle(p, 7.6 * s, dotGlow);
      canvas.drawCircle(p, 6.4 * s, dot);
    }
  }

  /// Shield outline inside [x0, x1] x [y0, y1].
  Path _shieldPath(double x0, double x1, double y0, double y1) {
    final cx = (x0 + x1) / 2;
    final top = y0 + (y1 - y0) * 0.10;
    final shoulder = y0 + (y1 - y0) * 0.19;
    final sideTop = y0 + (y1 - y0) * 0.27;
    final sideBottom = y0 + (y1 - y0) * 0.62;
    final bottom = y1 - (y1 - y0) * 0.05;
    return Path()
      ..moveTo(cx, top)
      ..lineTo(x1 - (x1 - x0) * 0.14, shoulder)
      ..quadraticBezierTo(
        x1 - (x1 - x0) * 0.09,
        shoulder + (y1 - y0) * 0.04,
        x1 - (x1 - x0) * 0.10,
        sideTop,
      )
      ..lineTo(x1 - (x1 - x0) * 0.10, sideBottom)
      ..quadraticBezierTo(
        x1 - (x1 - x0) * 0.11,
        bottom - (y1 - y0) * 0.10,
        cx,
        bottom,
      )
      ..quadraticBezierTo(
        x0 + (x1 - x0) * 0.11,
        bottom - (y1 - y0) * 0.10,
        x0 + (x1 - x0) * 0.10,
        sideBottom,
      )
      ..lineTo(x0 + (x1 - x0) * 0.10, sideTop)
      ..quadraticBezierTo(
        x0 + (x1 - x0) * 0.09,
        shoulder + (y1 - y0) * 0.04,
        x0 + (x1 - x0) * 0.14,
        shoulder,
      )
      ..close();
  }

  Path _mPath(double x0, double x1, double y0, double y1) {
    final left = x0 + (x1 - x0) * 0.345;
    final right = x1 - (x1 - x0) * 0.345;
    final barTop = y0 + (y1 - y0) * 0.445;
    final barBottom = y0 + (y1 - y0) * 0.705;
    final mid = y0 + (y1 - y0) * 0.615;
    return Path()
      ..moveTo(left, barBottom)
      ..lineTo(left, barTop)
      ..lineTo((x0 + x1) / 2, mid)
      ..lineTo(right, barTop)
      ..lineTo(right, barBottom);
  }

  List<Offset> _mDots(double x0, double x1, double y0, double y1) {
    // Same geometry as _mPath, for the three round ends.
    final w = x1 - x0, h = y1 - y0;
    final xL = x0 + w * 0.345;
    final xR = x1 - w * 0.345;
    final yTop = y0 + h * 0.445;
    final yMid = y0 + h * 0.615;
    return [Offset(xL, yTop), Offset(xR, yTop), Offset((x0 + x1) / 2, yMid)];
  }

  @override
  bool shouldRepaint(_NeonShieldPainter oldDelegate) =>
      oldDelegate.primary != primary || oldDelegate.accent != accent;
}

/// A slow-rotating conic sheen, clipped to [size]; used by the setup wizard hero.
class NeonSheen extends StatelessWidget {
  final double size;
  final Color color;
  final double turns;
  const NeonSheen({
    super.key,
    required this.size,
    required this.color,
    this.turns = 0,
  });

  @override
  Widget build(BuildContext context) {
    return Transform.rotate(
      angle: turns * 2 * math.pi,
      child: Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          gradient: SweepGradient(
            colors: [
              color.withValues(alpha: 0.35),
              Colors.transparent,
              color.withValues(alpha: 0.18),
              Colors.transparent,
            ],
          ),
        ),
      ),
    );
  }
}
